import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"遯","description":"焦氏易林注 - 遯","frontmatter":{"title":"遯","description":"焦氏易林注 - 遯"},"headers":[],"relativePath":"classics/jiaoyilin/033.md","filePath":"classics/jiaoyilin/033.md"}'),l={name:"classics/jiaoyilin/033.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="遯" tabindex="-1">遯 <a class="header-anchor" href="#遯" aria-label="Permalink to “遯”">​</a></h1><h3 id="遯-1" tabindex="-1">遯 <a class="header-anchor" href="#遯-1" aria-label="Permalink to “遯”">​</a></h3><h3 id="遯之乾" tabindex="-1">遯之乾 <a class="header-anchor" href="#遯之乾" aria-label="Permalink to “遯之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>軟弱無輔，不能自理。意在外野，心懷勞苦，雖憂不殆。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《遯》象。遯伏臨，上坤為柔，故曰軟弱。坤為野、為心、為憂苦，震往故曰意在外野。坤為萬物，役故曰勞。○不殆，宋元本作無但，依汲古。</p><h3 id="遯之坤" tabindex="-1">遯之坤 <a class="header-anchor" href="#遯之坤" aria-label="Permalink to “遯之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>周成之隆，刑措無兇。太宰贊佑，君子作仁。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此仍用遇卦象。遯伏臨，震為周。坤為刑，震為主，故曰太宰。艮為君子，震為仁。○太宰，汲古作大眾，依宋元本。佑，元本作右，依宋本、汲古。太宰謂周公。</p><h3 id="遯之屯" tabindex="-1">遯之屯 <a class="header-anchor" href="#遯之屯" aria-label="Permalink to “遯之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>穴有孤烏，坎生蝦蟆。象去萬裡，不可得捕。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>艮為穴、為黔啄、為烏，坎孤故曰穴有孤烏。上坎震為生，伏巽為蝦蟆，艮為象，又為鼻，象鼻最大故取之。坤為萬裡，艮手為捕，坤亡故不可得捕。○孤，依宋元本，汲古作狐。去，宋元本作出，依汲古。</p><h3 id="遯之蒙" tabindex="-1">遯之蒙 <a class="header-anchor" href="#遯之蒙" aria-label="Permalink to “遯之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>俱為天門，雲過吾西。伯氏嫉妬，與我無恩。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮坤皆居戌亥，故曰俱為天門。坤為吾，坎為雲，位西，故曰雲過吾西。震為伯，坎為嫉妬、為恩澤，坤為我，坤虛故無恩。○門，汲古作民，西作面，伯氏作治民，均依宋元。</p><h3 id="遯之需" tabindex="-1">遯之需 <a class="header-anchor" href="#遯之需" aria-label="Permalink to “遯之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>三首六目，政多煩惑。皋陶喑聾，亂不可從。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>乾首，離卦數三，故曰三首。離目，坎數六，故曰六目。通《晉》。坤為政、為多，離為煩，坎為惑，故政多煩惑。艮為皋，離火為陶，坎耳坤閉，故曰皋陶喑聾。離為亂，震為從，震覆故不可從。○首，宋本作手，依元本。</p><h3 id="遯之訟" tabindex="-1">遯之訟 <a class="header-anchor" href="#遯之訟" aria-label="Permalink to “遯之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>德積不輕，辭王釣耕。三媒不已，大福來成。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>通《明夷》。坤為積、為重，故曰不輕。震為言、為王、為耕，故曰辭王釣耕。坎為合、為媒，震數三，故曰三媒。三媒，即三聘。乾為福、為大，故曰大福。用伊呂事。○辭王釣耕，汲古作辭出真心，依宋元本、局本。</p><h3 id="遯之師" tabindex="-1">遯之師 <a class="header-anchor" href="#遯之師" aria-label="Permalink to “遯之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>堅固相親，日篤無患。六體不易，執以安全。雨師駕西，濡我轂輪。張伯李季，各坐關門。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>坎為堅固，坤順故相親，坤厚故曰篤。坎為患，震樂故無患。坤為身體，坎數六，故曰六體。坤為安全。坎為雨師，位西，故曰雨師駕西。又為輪轂、為濡，震為伯、為張、為李。遯艮為季、為坐，坤為門，坤閉故關門。○第二句汲古作日用自完。執以作孰為，坐作噬，均依宋元本。</p><h3 id="遯之比" tabindex="-1">遯之比 <a class="header-anchor" href="#遯之比" aria-label="Permalink to “遯之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>方內不行，輻摧輪傷。馬楚踶甚，受子閔時。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>坤為方、為內，坎陷艮止故不行。坎為輪輻，坎破故摧傷。震為馬，震倒足向上故踶。坤為受，艮為時，坎為閔。楚，不馴貌。受子應為壽子。《桓十六年》：&quot;衛朔構急子，使於齊，將以盜殺諸塗，壽子閔其兄，乃自載其旌以行。&quot;○第三句汲古作馬禁堤與，受作愛，均依宋元本、局本。</p><h3 id="遯之小畜" tabindex="-1">遯之小畜 <a class="header-anchor" href="#遯之小畜" aria-label="Permalink to “遯之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>畜牝無駒，養雞不雛。群羊三歲，不生兩頭。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>五陽畜一陰故曰畜牝。震為馬，震伏故無駒。兌為雞，兌折故不雛。兌羊，乾為歲，離卦數三，故曰三歲，二至上正覆雨兌，故曰群羊。乾為頭，兌卦數二，故曰兩頭。乾為生，巽隕落故不生。</p><h3 id="遯之履" tabindex="-1">遯之履 <a class="header-anchor" href="#遯之履" aria-label="Permalink to “遯之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>老耄罷極，無取中直。懸輿致仕，得歸鄉國。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。坤老，坎為勞卦，故曰疲極。坎矯輮故無取中直。艮手為取，坤為輿在上，艮為手，故曰懸輿。艮為官、為清高，故曰致仁。坤為鄉國，震為歸。○國，宋元本作裡，依汲古。</p><h3 id="遯之泰" tabindex="-1">遯之泰 <a class="header-anchor" href="#遯之泰" aria-label="Permalink to “遯之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>縮緒亂絲，手與為災。越畝逐兔，斷其褌襦。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>巽為繩、為緒、為絲，巽倒故曰亂縮。伏艮為手，坤喪兌折故曰為災。坤為畝，震為兔、為越、為逐，坤震連體故曰越畝逐兔。兌為決斷，伏巽為褌，震為襦，皆裡衣也。○宋本災作哭，褌作禪，均依汲古。</p><h3 id="遯之否" tabindex="-1">遯之否 <a class="header-anchor" href="#遯之否" aria-label="Permalink to “遯之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>海老水乾，魚鱉蕭索。槁落無潤，獨有沙石。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>坤為海水，乾為老，故曰海老水乾。巽為魚，艮為鱉，坤敝故蕭索。巽為槁，風散，故槁落，艮為沙石，故無潤。○蕭，宋元本作盡，依汲古。槁，汲古作高，潤作澗，均依宋元本。</p><h3 id="遯之同人" tabindex="-1">遯之同人 <a class="header-anchor" href="#遯之同人" aria-label="Permalink to “遯之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>入市求鹿，不見頭足。終日至夜，竟無所得。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>中爻巽為市、為入，故曰入市。旁通《師》。《師》震為鹿，坎為大首，震為足，坎伏故不見頭足。離為日，坎為夜，故曰終日。坤喪坎失故無所得。○頭，汲古訛頓，依宋元本。</p><h3 id="遯之大有" tabindex="-1">遯之大有 <a class="header-anchor" href="#遯之大有" aria-label="Permalink to “遯之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>築門壅戶，虎臥當道。驚我驊騮，不利出處。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>乾為門戶，乾實故曰築壅。乾為道，兌虎在前故曰當道。乾為馬，故曰驊騮。乾在下，兌毀折故不利出處。</p><h3 id="遯之謙" tabindex="-1">遯之謙 <a class="header-anchor" href="#遯之謙" aria-label="Permalink to “遯之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>陶朱白圭，善賈息資。公子王孫，富貴不貧。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>通《履》。乾為朱，離火為陶，故曰陶朱。乾為玉、為圭，巽白，故曰白圭。巽為商賈、為利，故能息資。本卦震為公子、為王，艮為孫、為貴，坤富故不貧。</p><h3 id="遯之豫" tabindex="-1">遯之豫 <a class="header-anchor" href="#遯之豫" aria-label="Permalink to “遯之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>王良善御，伯樂知馬。周旋步驟，行中規矩。止息有節，延命壽考。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為帝、為王，艮為賢良，故曰王良。震為樂、為伯，故曰伯樂。馬御亦震象也。震為周、為旋、為步驟、為行，坎為規，坤為矩。艮為止息、為節、為壽考。○節，汲古作前，依宋元本。</p><h3 id="遯之隨" tabindex="-1">遯之隨 <a class="header-anchor" href="#遯之隨" aria-label="Permalink to “遯之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>堯問尹壽，聖德增益。使民不懼，安無怵惕。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>震為帝，故曰堯。艮為壽，《新序》：&quot;堯學乎尹壽&quot;。震為言故曰問。坎為聖，震為生，故曰聖德增益。坎為民、為怵惕，震樂艮安故不懼。○尹壽，宋元本作伊舜，汲古作大舜，依《歸妹》之《小畜》校。翟雲《小畜》作尹爵，爵即壽之訛字。</p><h3 id="遯之蠱" tabindex="-1">遯之蠱 <a class="header-anchor" href="#遯之蠱" aria-label="Permalink to “遯之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>昭公失常，季氏悖狂。遜齊處鄆，喪其寵身。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>互大離為昭，艮為常，在外故失常，坎為失也，事見前。艮為季，震為狂，巽齊坎陷故曰遜齊、曰處鄆。艮為邑，故曰鄆。艮為身，兌折故喪。○遜，汲古作遊，依宋元本。</p><h3 id="遯之臨" tabindex="-1">遯之臨 <a class="header-anchor" href="#遯之臨" aria-label="Permalink to “遯之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>昬莫不行，候旦待明。覆住止後，未得相從。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>坤為昏暮，震為行，坤閉故不行。伏艮止故曰候、曰待。震為旦、為明、為復、為後，艮止故不從。《左傳》雲不行之謂臨，林義與左氏同。○復，宋元作從，依汲古。</p><h3 id="遯之觀" tabindex="-1">遯之觀 <a class="header-anchor" href="#遯之觀" aria-label="Permalink to “遯之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>安上宜官，一日九遷。升擢超等，牧養常山。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>艮為官、為安，在上卦，故曰安上宜官。艮為日，伏乾，乾卦數一，又數九，艮官在上，故曰一日九遷。艮手為擢，巽為高，故曰超等。坤為牧養，艮山故曰常山。○上，汲古作止，依宋元本。</p><h3 id="遯之噬嗑" tabindex="-1">遯之噬嗑 <a class="header-anchor" href="#遯之噬嗑" aria-label="Permalink to “遯之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>去惡就兇，東西多訟，行者無功。離為惡人，坎為兇，震往故去惡就兇。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>離東坎西，初至四兩震言相對故多訟。震為行，坎失故無功。</p><h3 id="遯之賁" tabindex="-1">遯之賁 <a class="header-anchor" href="#遯之賁" aria-label="Permalink to “遯之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>老馬垂耳，不見百裡。君子弗恃，商人莫取，無與為市。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>震為馬，坎疾故老。坎為耳，在下故曰垂耳。震為百，艮為裡，坎隱故不見。艮為君子，震為商人，艮手為取，坎失故莫取。巽為市，巽伏故無與為市，言馬老不能遠行皆不顧也。</p><h3 id="遯之剝" tabindex="-1">遯之剝 <a class="header-anchor" href="#遯之剝" aria-label="Permalink to “遯之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>蝸螺生子，深目黑醜。似類其母，雖或相就，眾人莫取。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為蝸螺、為觀、為目，形長故曰深目。坤為黑、為醜、為母、為近，故曰似類其母。坤為眾，艮手為取，以其醜故莫取。○蝸，汲古作蟙，目作自，依宋元本。</p><h3 id="遯之復" tabindex="-1">遯之復 <a class="header-anchor" href="#遯之復" aria-label="Permalink to “遯之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>百足俱行，相輔為強。三聖翼事，王室寵光。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>百足，蟲名。震為足、為百、為行、為強，坤為輔，重坤，故曰相輔。坤伏乾，乾為聖，震數三，故曰三聖。坤為事，震為翼、為王、為寵光。○王室，元本作不見，依宋本、汲古。</p><h3 id="遯之無妄" tabindex="-1">遯之無妄 <a class="header-anchor" href="#遯之無妄" aria-label="Permalink to “遯之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>容民畜眾，履德有信。大人受福，童蒙憂惑，利無所得。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>乾伏坤，坤為民、為眾，艮止，故容民畜眾。震為履，乾為德、為信、為大人、為福。艮為童蒙，伏坤為憂惑，巽為利風散，故無得。</p><h3 id="遯之大畜" tabindex="-1">遯之大畜 <a class="header-anchor" href="#遯之大畜" aria-label="Permalink to “遯之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>左跌右僵，前躓觸桑。其指據石，傷其弟兄。老蠶不作，家無織帛。貴貨賤身，留連久客。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>中爻震為左，兌為右，兌毀折，故左跌右僵。乾為前，兌折故前躓。震為桑，在前故觸桑。艮為指、為石，震為兄，艮為弟，兌折故傷其弟兄。卦通《萃》。萃中爻巽為蠶，坤為老，兌毀故不作蠒。艮為家，坤為帛，巽為織，巽隕坎失故無織。艮為貴，坤為財貨、為身、為賤，故曰貴貨賤身。艮為留連，震為客。○末句宋元本作久流連客，依汲古。</p><h3 id="遯之頤" tabindex="-1">遯之頤 <a class="header-anchor" href="#遯之頤" aria-label="Permalink to “遯之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>昏人旦明，賣食老昌。國祚東表，號稱太公。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>坤為昏，震為人、為旦，艮為明，故曰昏人旦明，言人由貧賤而富貴，如人處昏夜而忽遇旦明也。震為食、為商旅，故曰賣食。坤老震昌，故曰老昌，言薑尚始賣飯朝歌，老而受封也。坤為國，震為東，震言為號、為稱，坤伏乾，乾為父、為太公，譙周雲呂望嘗屠牛於朝歌，賣飯於孟津。○旦，宋元本作宜，依汲古。</p><h3 id="遯之大過" tabindex="-1">遯之大過 <a class="header-anchor" href="#遯之大過" aria-label="Permalink to “遯之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>敝笱在梁，魴逸不禁。漁父勞苦，焦喉乾口，虛空無有。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>通《頤》。坤為敝，震為笱，艮為梁，故曰敝笱在梁。坤為魚，震為逸，故曰魴逸不禁。坤聚為漁，伏乾為父，坤役故勞苦。震為喉、為口，艮火，故焦喉乾口。坤虛故無有。○焦喉，宋元本作藏空，無第五句，均依汲古。敝笱，《齊詩》篇名，齊人以莊公不能防閑文薑而作，故曰魴逸不禁。</p><h3 id="遯之坎" tabindex="-1">遯之坎 <a class="header-anchor" href="#遯之坎" aria-label="Permalink to “遯之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>盛中後跌，衰老復掇。盈滿減毀，疾羸肥腯。鄭昭失國，重耳興立。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>坎中滿故曰盛，中坎陷故跌，震為後，故後跌。坎疾病故衰老。艮手為掇，坎破故盈毀，坎疾故肥腯者羸，坎平故曰鄭。《釋名》雲：&quot;鄭，町也，地多平町町然也&quot;。艮為昭、為國，坎失故曰鄭昭失國，習坎故曰重耳。鄭昭被弒，在桓十七年，晉文入國在僖二十四年，事不相涉，此但取卦象耳。○老，汲古作者，減作或，羸作嬴，均依宋元本。興，宋元本作與，依汲古。</p><h3 id="遯之離" tabindex="-1">遯之離 <a class="header-anchor" href="#遯之離" aria-label="Permalink to “遯之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>折亡破甕，使我貧困。與母生分，別離異門。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>伏震為甕，中爻兌毀故曰折、曰破。離虛故貧。坎陷故困。坤為母，坤二五之乾成離，乾二五之坤成坎，坎中爻震，震生，故曰與母生分，言坎居坤中，使坤分析，所謂坎折坤也。坎中爻艮，艮為門，正覆兩艮相反故異門，亡疑為缶之訛字。</p><h3 id="遯之鹹" tabindex="-1">遯之鹹 <a class="header-anchor" href="#遯之鹹" aria-label="Permalink to “遯之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>野有積庾，嗇人駕取。不逢狼虎，暮歸其宇。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>通《損》。坤為野、為積，艮為庾，震為嗇人、為駕，艮手為取，艮為虎狼，艮在外故不逢。坤為暮，艮為守，伏震為歸。○虎與宇韻，宋元本作虎狼，非，依汲古。</p><h3 id="遯之恆" tabindex="-1">遯之恆 <a class="header-anchor" href="#遯之恆" aria-label="Permalink to “遯之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>襁褓孩呱，冠帶成家。出門如賓，父母何憂。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>巽為襁褓，兌為孩、為呱，乾為冠，巽為帶，伏艮為家，成家，言由孩提而成立也。乾為門，震出，震為賓客，故曰出門如賓。乾為父，伏坤為母，坎為憂，乾福震樂故不憂。○呱，汲古作孤，依宋元本。</p><h3 id="遯之遯" tabindex="-1">遯之遯 <a class="header-anchor" href="#遯之遯" aria-label="Permalink to “遯之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>三塗五嶽，陽城太室。神明所保，獨無兵革。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>艮為徑，納丙，數三，故曰三塗。艮為山，互巽，卦數五，故曰五嶽。三塗、五嶽、太室，皆山名。陽城，谷名，艮為谷也。乾為神明、為保佑，乾數無，故曰獨無兵革。艮為刀兵、為膚革。○保，汲古作住，依宋元本。</p><h3 id="遯之大壯" tabindex="-1">遯之大壯 <a class="header-anchor" href="#遯之大壯" aria-label="Permalink to “遯之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>陳力就列，官職並廢。手不勝盆，失其寵門。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>通《觀》。震為陳力、為就列，孟子：陳力就列不能者止。艮為官職，艮伏故並廢。艮為手，震為盆，坤弱故不勝盆。乾為寵、為門，坤喪故失。○並，汲古作無，依宋元本。</p><h3 id="遯之晉" tabindex="-1">遯之晉 <a class="header-anchor" href="#遯之晉" aria-label="Permalink to “遯之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>積雪大寒，萬物不生。陰制庶士，時木冬貧。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坎為雪、為積、為寒，坤為萬物，坤殺故不生。坤為陰、為庶，艮為時，坎為冬，坤為貧。庶士二字必有訛。○冬，依宋元本，汲古作寒。</p><h3 id="遯之明夷" tabindex="-1">遯之明夷 <a class="header-anchor" href="#遯之明夷" aria-label="Permalink to “遯之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>龍鬬時門，失理傷賢。內畔生賊，自為心疾。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為龍、為門、為時，坤為門，故曰龍鬬時門。坤為理，震為賢，坎為失、為傷，故曰失理傷賢。坤為內，離為畔亂，震為生，坎為賊、為心、為疾。○時，汲古作海，依宋元本。《左傳昭十九年》：&quot;龍鬬鄭時門外&quot;。</p><h3 id="遯之家人" tabindex="-1">遯之家人 <a class="header-anchor" href="#遯之家人" aria-label="Permalink to “遯之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>犬畏猛虎，依人為輔。三夫執戟，伏不敢起，身安無咎。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《遯》象。艮為犬，乾為虎，伏震為人，兌為輔，震為夫，數三，故曰三夫。艮為執、為戟，震為起，巽伏故不敢起。艮為身、為安，安故無咎。○犬，宋本作狗，汲古作不，依元本。猛，元本作狼，依宋本、汲古。戟，汲古作獸，依宋元本。起，宋元本作趨，依汲古。</p><h3 id="遯之睽" tabindex="-1">遯之睽 <a class="header-anchor" href="#遯之睽" aria-label="Permalink to “遯之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>南山高岡，回隤難登。道路遼遠，行者無功。憂不成兇，惡亦消去。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>此仍用《遯》象。艮山納丙，故曰南山、曰高岡。巽進退不果，故曰回隤難登。艮為道路，乾為遼遠、為行，巽隕故無功。坤為憂、為惡，坤伏故不兇、故消去。○崗，宋元本作罡，路作卑，均依汲古。</p><h3 id="遯之蹇" tabindex="-1">遯之蹇 <a class="header-anchor" href="#遯之蹇" aria-label="Permalink to “遯之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>逢時陽遂，富且貴尊。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>艮為時，陽居五故遂、故富且貴。艮為尊貴。</p><h3 id="遯之解" tabindex="-1">遯之解 <a class="header-anchor" href="#遯之解" aria-label="Permalink to “遯之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>求我所欲，得其利福，終身不辱。盈盛之門，高屋先覆，群失邦國。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>此仍用《遯》象。艮為求，互巽為利，乾為福，故曰得其利福。艮為終、為身，艮貴故不辱。乾為盈盛、為門戶，巽為高，艮為屋，巽為隕落故曰高屋先覆。艮為邦國，乾為君，在外故曰君失邦國。○先，汲古作光，末句作君先其固，茲依宋元本。</p><h3 id="遯之損" tabindex="-1">遯之損 <a class="header-anchor" href="#遯之損" aria-label="Permalink to “遯之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>安坐至暮，禍災不到。利詰姦妖，罪人不赦。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>艮為安坐，坤為暮，故曰安坐至暮。坤為禍災，震解故禍災不到。三至上兩震言相對故利詰。坤為姦妖、為罪過，震為人，坤殺故罪人弗赦。○末句汲古作皇宥不赦。姦妖，汲古作妬姝，均依宋元本。</p><h3 id="遯之益" tabindex="-1">遯之益 <a class="header-anchor" href="#遯之益" aria-label="Permalink to “遯之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>膠車駕東，與雨相逢。五楘解墮，頓輈獨坐，憂為身禍。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>詳《大過》之《蠱》，此用伏象《恆》。恆蠱象多同，故詞同。○頓輈，汲古作頹杌，依宋元本。坐，宋本作宿，依汲古。</p><h3 id="遯之夬" tabindex="-1">遯之夬 <a class="header-anchor" href="#遯之夬" aria-label="Permalink to “遯之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>擇日高飛，遠至東齊。見孔聖師，使我和諧。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>此用《遯》象。乾為日，艮為高，巽為齊，伏震為東、為孔，乾為聖。○遠，宋元本作遂，依汲古。末句汲古作徒我相諧，依宋元本。</p><h3 id="遯之姤" tabindex="-1">遯之姤 <a class="header-anchor" href="#遯之姤" aria-label="Permalink to “遯之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>陳媯敬仲，兆興齊薑。乃適營丘，八世大昌。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。震為陳，乾為敬，坤拆為兆。巽為齊薑，故曰兆與齊薑。震為丘陵，巽數八，故曰八世大昌。震為昌也。事詳《屯》之《噬嗑》</p><h3 id="遯之萃" tabindex="-1">遯之萃 <a class="header-anchor" href="#遯之萃" aria-label="Permalink to “遯之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>缺埒無墠，難從東西。毀破我盆，泛棄酒食。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>埒，短垣也。《爾雅》：&quot;山上有水埒&quot;，卦下坤為水，艮為埒，而兌上缺，故曰缺埒。坤為墠，兌毀故無墠。兌為西，震為東、為從，震覆故難從。震為盆，震覆兌毀故破我盆。兌為酒食，在外，中爻艮手，故曰泛棄酒食。○首句汲古作缺將無憚，非，依宋元本。</p><h3 id="遯之升" tabindex="-1">遯之升 <a class="header-anchor" href="#遯之升" aria-label="Permalink to “遯之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>中夜犬吠，盜在廬外。神光佐助，消散歸去。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>通《無妄》。坤為夜，艮為犬，震為吠，巽為盜，艮為廬，巽在艮上故曰盜在廬外。震為神光，兌為輔，故曰神光佐助。巽風為散，震為歸去。</p><h3 id="遯之困" tabindex="-1">遯之困 <a class="header-anchor" href="#遯之困" aria-label="Permalink to “遯之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>雷車不藏，隱隱西行。霖雨三旬，流為河江，使我憂兇。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>通《賁》。震為雷、為車，坎伏震出故不藏。坎隱兌西故曰隱隱西行。坎為雨，互大坎，下坎故曰霖雨。中爻震數三，故曰三旬，坎水故曰流為河江。坎為憂兇。○我，依汲古，宋元本作國。</p><h3 id="遯之井" tabindex="-1">遯之井 <a class="header-anchor" href="#遯之井" aria-label="Permalink to “遯之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>老河空虛，舊井無魚。利得不饒，避患東鄰。禍來入門，使多悔存。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>坎為河、為舊，故曰老河。離為空虛，兌為井，故曰舊井。巽為魚，坎失故無魚。巽為利，坎瘠故不饒。坎為患，坎隱故避患。離為東鄰、為禍，伏艮為門，巽入，故曰禍來入門。坎為悔。○來入，宋元本作入我，依汲古。</p><h3 id="遯之革" tabindex="-1">遯之革 <a class="header-anchor" href="#遯之革" aria-label="Permalink to “遯之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>福德之士，歡悅日喜。夷吾相國，三歸為臣，貴流子孫。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。震為福德、為士、為歡喜，坤為夷、為吾、為國，兌為輔相，震數三，震反為歸，坤為臣，故曰三歸為臣。艮為貴、為孫，震為子，坤為水故曰貴流子孫。○貴，宋元本作賞，依汲古。《論語》&quot;管氏有三歸&quot;註：取三姓女。朱子雲臺名。</p><h3 id="遯之鼎" tabindex="-1">遯之鼎 <a class="header-anchor" href="#遯之鼎" aria-label="Permalink to “遯之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>清人高子，久屯外野。逍遙不歸，思我慈母。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。艮為清高，震為人、為子，故曰清人高子。艮止為久、為屯，坤為野，震為逍遙、為歸，坤迷故不歸。坎為思，坤為我，慈母也。</p><h3 id="遯之震" tabindex="-1">遯之震 <a class="header-anchor" href="#遯之震" aria-label="Permalink to “遯之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>驄黑，東歸高鄉。白虎推輪，蒼龍把衡。朱雀導引，靈鳥載遊。遠扣天門，入見真君，馬全人安。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震馬故曰驄。坎黑，對象巽，巽髪，故曰黑。震為東、為歸，艮為高鄉、為虎，震白坎輪，艮手為推，故曰白虎推輪。震為龍，色青，故曰蒼龍。坎為衡，互大離為朱雀、為靈鳥，震往為導引、為遊。艮為天門，艮手為扣，震為帝，故為真君、為馬、為人，艮為安全。○全，元本作南，依宋本、汲古。靈鳥，宋元本作虛烏，遠作逐，作馬安人全，均依汲古。</p><h3 id="遯之艮" tabindex="-1">遯之艮 <a class="header-anchor" href="#遯之艮" aria-label="Permalink to “遯之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>路多枳棘，前刺我足。不利旅客，為心作毒。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>艮為路，坎為棘，中爻震為足，坎棘故刺足。震為旅客，坎為毒、為心。</p><h3 id="遯之漸" tabindex="-1">遯之漸 <a class="header-anchor" href="#遯之漸" aria-label="Permalink to “遯之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>端坐生患，憂來入門，使我不安。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>艮為端坐，坎為患，故曰端坐生患。坎為憂，艮為門，巽入故曰憂來入門。艮為安，坎險故不安。</p><h3 id="遯之歸妹" tabindex="-1">遯之歸妹 <a class="header-anchor" href="#遯之歸妹" aria-label="Permalink to “遯之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>小陬之市，利不足喜。二世積仁，蒙其祖先。匪躬之言，狂悖為患。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>通《漸》。巽為市，坎狹故曰小陬之市。陬，隅也。巽為利，坎憂故不喜。本卦兌卦數二，震仁坎積故曰二世積仁。艮為祖，坎為蒙，故曰蒙其祖先。坤為躬，本卦震為言、為狂，坎為悖、為患。</p><h3 id="遯之豐" tabindex="-1">遯之豐 <a class="header-anchor" href="#遯之豐" aria-label="Permalink to “遯之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>登高望時，見樂無憂。求利南國，與寶相得。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>巽為高，震為時、為登，離為目、為望，故曰登高望時。坎為憂，震樂故無憂。巽為利，伏艮為求、為國，離南故曰南國。震為玉、為寶，坎為得也。</p><h3 id="遯之旅" tabindex="-1">遯之旅 <a class="header-anchor" href="#遯之旅" aria-label="Permalink to “遯之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>跛足息肩，有所忌難。金城鐵郭，以銅為關。藩屏自衛，安土無患。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。震為足，坎蹇故跛足。艮為肩，艮止，故息肩。坎為忌難，艮為金鐵、為銅、為城郭、為關、為藩屏，震為衛，故曰藩屏自衛。艮為安，坤為上，坎為患，震出故無患。○跛，宋元本作疏，土作上，依汲古。</p><h3 id="遯之巽" tabindex="-1">遯之巽 <a class="header-anchor" href="#遯之巽" aria-label="Permalink to “遯之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>江有沱泛，思附君子。仲氏爰歸，不我肯顧，侄娣悔恨。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>艮震中爻坎為江、為沱泛、為思，艮為君子，故曰思附君子。坎為仲，震反為歸，女嫁曰歸。爰歸者，言仲氏已嫁也。艮為顧，坎蔽故不顧。兌為侄娣，坎為悔恨。○《詩》：&quot;江有沱，江有泛，之子歸，不我顧&quot;，林用其意，與毛合。○仲氏爰歸，宋元本作伯仲爰歸，汲古作伯仲處市，依局本《明夷》之《噬嗑》校。又江有汲古作江水，依宋元本。</p><h3 id="遯之兌" tabindex="-1">遯之兌 <a class="header-anchor" href="#遯之兌" aria-label="Permalink to “遯之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>芽櫱生達，陽倡於外。左手執鑰，公言錫爵。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。中爻震為芽櫱、為生，艮上下卦皆陽居上，故曰陽倡於外。震為左、為鑰，艮手為執，故曰左手執鑰。震為言、為爵、為諸侯，故曰公。二語皆詩辭。</p><h3 id="遯之渙" tabindex="-1">遯之渙 <a class="header-anchor" href="#遯之渙" aria-label="Permalink to “遯之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>雲夢苑囿，萬物繁熾。犀象玳瑁，荊人以富。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>坎水為雲夢，艮為苑囿，震為萬物、為蕃熾。艮為犀象、為玳瑁，震為荊、為人、為富。</p><h3 id="遯之節" tabindex="-1">遯之節 <a class="header-anchor" href="#遯之節" aria-label="Permalink to “遯之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>渠戎萬裡，晝夜愁苦。甲戎服，雖荷不賊。鷹鸇之殃，害不能傷。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>坎為戎、為溝瀆，故曰渠戎，《後漢書》：&quot;義渠戎在涇北&quot;。震為萬裡，伏離為晝，坎為夜，坎憂故愁苦。艮為甲，坎隱故甲，坎西為戎，震為服，故曰甲戎服。艮為負荷，坎為賊，在外故不賊。艮為鷹鸇，坎為殃害，震解故不傷。○殃，宋元本作殘，依汲古。</p><h3 id="遯之中孚" tabindex="-1">遯之中孚 <a class="header-anchor" href="#遯之中孚" aria-label="Permalink to “遯之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>鎡基逢時，稷契皋陶。貞良得願，微子解囚。市恐無虎，謾言妄語。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>鎡基，鋤也。震為鎡基，艮為時，震為稷、為竹，故為契。艮為皋、為火，故為陶，故曰稷契皋陶。艮為貞良、為小，震為子，故曰微子。艮為拘，故為囚，震出故解囚。巽為市，艮為虎，風散故無虎。中爻正反兩震言相背，故曰謾言妄語。○恐，宋元作空，言作誑，均依汲古。汲古作《既濟》林，依宋元本。</p><h3 id="遯之小過" tabindex="-1">遯之小過 <a class="header-anchor" href="#遯之小過" aria-label="Permalink to “遯之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>騎騅與蒼，南賈太行。逢駁猛虎，為所吞殤，葬於渭陽。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為馬，東方色青，故騎騅與蒼。騅蒼，青色馬也。震為商賈、為南，艮山故曰太行。艮為駁、為猛虎，兌口為吞折、為殤，坎為葬、為渭，渭濁，坎黑，故象之。水北為陽，坎北故曰渭陽。凡《易林》用字取象之精皆如此。○駁，汲古作蛟，殤作飡，依宋元本。</p><h3 id="遯之既濟" tabindex="-1">遯之既濟 <a class="header-anchor" href="#遯之既濟" aria-label="Permalink to “遯之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>出門東行，日利辰良。步騎與駟，經歷宗邦。暮宿北燕，與樂相逢。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用《遯》象。伏震為出、為東行，坤為門，故曰出門東行。乾為日，巽為利，艮時，故曰日利辰良。伏震為騎、為駟、為宗，坤為邦，乾坤相間隔，故曰經歷宗邦。坤為暮、為宿、為北，兌為燕，震為樂。○辰，宋元本作時，依汲古。宗，汲古作京，依宋元本。</p><h3 id="遯之未濟" tabindex="-1">遯之未濟 <a class="header-anchor" href="#遯之未濟" aria-label="Permalink to “遯之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>酒為歡伯，除憂來樂。福善入門，與君相索，使我有得。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>兼用半象。坎為酒，震為歡、為伯，坎為憂，震出故除憂，震福、艮善、巽入、艮門，故曰福善入門。震為君，艮為求索，離正反艮相對，故相索。坤我、坎得。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
